let currentHeroIndex = 0;

function initPatreonHero() {
    const heroSection = document.getElementById('homeHero');
    const heroCanvas = document.getElementById('heroCanvas');
    const slidesWrapper = document.getElementById('heroSlidesWrapper');
    const cursorFollower = document.getElementById('cursorFollowerPreview');
    const prevArrow = document.getElementById('heroArrowPrev');
    const nextArrow = document.getElementById('heroArrowNext');
    const quickViewBtn = document.getElementById('heroQuickViewBtn');

    if (!heroSection || !heroCanvas || !slidesWrapper) return;

    // 1. Render all background slide images for instant crossfades
    slidesWrapper.innerHTML = HERO_SLIDES.map((slide, idx) => `
        <div class="hero-slide-item ${idx === 0 ? 'active' : ''}" data-index="${idx}">
            <img class="hero-slide-bg" src="${slide.image}" alt="${slide.name}">
        </div>
    `).join('');

    updateHeroUI();

    // 2. Cursor Follower Physics (Smooth Spring Interpolation + 3D Tilt)
    let mouseX = window.innerWidth / 2;
    let mouseY = window.innerHeight / 2;
    let currX = mouseX;
    let currY = mouseY;
    let prevX = mouseX;
    let isInsideHero = false;

    const updateFollower = () => {
        if (isInsideHero) {
            currX += (mouseX - currX) * 0.16;
            currY += (mouseY - currY) * 0.16;
            const velocityX = mouseX - prevX;
            prevX = mouseX;
            const tilt = Math.max(-14, Math.min(14, velocityX * 0.35));

            if (cursorFollower) {
                cursorFollower.style.left = `${currX}px`;
                cursorFollower.style.top = `${currY}px`;
                cursorFollower.style.transform = `translate(18px, 18px) rotate(${tilt}deg)`;
            }
        }
        requestAnimationFrame(updateFollower);
    };
    requestAnimationFrame(updateFollower);

    // Track mouse movement
    window.addEventListener('mousemove', (e) => {
        mouseX = e.clientX;
        mouseY = e.clientY;

        const heroRect = heroSection.getBoundingClientRect();
        const inside = (
            e.clientX >= heroRect.left &&
            e.clientX <= heroRect.right &&
            e.clientY >= heroRect.top &&
            e.clientY <= heroRect.bottom
        );

        if (inside && !isInsideHero) {
            isInsideHero = true;
            if (cursorFollower) cursorFollower.classList.add('active');
        } else if (!inside && isInsideHero) {
            isInsideHero = false;
            if (cursorFollower) cursorFollower.classList.remove('active');
        }
    });

    // 3. Patreon-Style Click Anywhere Canvas Interaction
    heroCanvas.addEventListener('click', (e) => {
        // Ignore clicks on buttons, links, or already-stamped cards
        if (e.target.closest('button, a, .hero-active-piece-badge, .stamped-card, input, select')) {
            return;
        }

        const rect = heroCanvas.getBoundingClientRect();
        const clickX = e.clientX - rect.left;
        const clickY = e.clientY - rect.top;

        // A. Drop/Stamp an interactive preview card at cursor position
        spawnStampedCard(clickX, clickY);

        // B. Spawn glowing sparkle burst
        spawnSparkles(clickX, clickY);

        // C. Advance to next editorial slide
        changeHeroSlide(currentHeroIndex + 1);
    });

    // 4. Navigation Arrows
    if (prevArrow) {
        prevArrow.addEventListener('click', (e) => {
            e.stopPropagation();
            changeHeroSlide(currentHeroIndex - 1);
        });
    }

    if (nextArrow) {
        nextArrow.addEventListener('click', (e) => {
            e.stopPropagation();
            changeHeroSlide(currentHeroIndex + 1);
        });
    }

    // 5. Quick View button for current piece
    if (quickViewBtn) {
        quickViewBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            const currentSlide = HERO_SLIDES[currentHeroIndex];
            openQuickView(currentSlide.productId);
        });
    }
}

function changeHeroSlide(newIndex) {
    if (newIndex < 0) newIndex = HERO_SLIDES.length - 1;
    currentHeroIndex = newIndex % HERO_SLIDES.length;

    // Crossfade background slides
    const slideItems = document.querySelectorAll('.hero-slide-item');
    slideItems.forEach((slideEl, idx) => {
        slideEl.classList.toggle('active', idx === currentHeroIndex);
    });

    updateHeroUI();
}

function updateHeroUI() {
    const slide = HERO_SLIDES[currentHeroIndex];
    if (!slide) return;

    const tagEl = document.getElementById('heroSlideTag');
    const headlineEl = document.getElementById('heroHeadline');
    const subtitleEl = document.getElementById('heroSubtitle');
    const activeThumbEl = document.getElementById('heroActiveThumb');
    const activeNameEl = document.getElementById('heroActiveName');
    const activePriceEl = document.getElementById('heroActivePrice');
    const counterEl = document.getElementById('heroSlideCounter');

    // Cursor follower preview elements
    const cursorThumb = document.getElementById('cursorPreviewImg');
    const cursorTitle = document.getElementById('cursorPreviewTitle');

    if (tagEl) tagEl.textContent = slide.tag;
    if (headlineEl) headlineEl.innerHTML = slide.headline;
    if (subtitleEl) subtitleEl.textContent = slide.subtitle;
    if (counterEl) counterEl.textContent = `0${currentHeroIndex + 1} / 0${HERO_SLIDES.length}`;

    if (activeThumbEl) activeThumbEl.src = slide.image;
    if (activeNameEl) activeNameEl.textContent = slide.name;
    if (activePriceEl) activePriceEl.textContent = `${formatPrice(slide.priceINR)} • ${slide.finish}`;

    if (cursorThumb) cursorThumb.src = slide.nextThumb;
    if (cursorTitle) cursorTitle.textContent = slide.nextName;
}

// Spawn stamped polaroid card at cursor location
function spawnStampedCard(x, y) {
    const container = document.getElementById('stampedCardsContainer');
    const canvas = document.getElementById('heroCanvas');
    if (!container || !canvas) return;

    const currentSlide = HERO_SLIDES[currentHeroIndex];
    const rect = canvas.getBoundingClientRect();

    const card = document.createElement('div');
    card.className = 'stamped-card';

    // Position around click coordinate with boundary padding
    const posX = Math.max(20, Math.min(rect.width - 200, x - 85));
    const posY = Math.max(20, Math.min(rect.height - 230, y - 85));
    const rot = (Math.random() * 16 - 8).toFixed(1);

    card.style.left = `${posX}px`;
    card.style.top = `${posY}px`;
    card.style.transform = `rotate(${rot}deg)`;

    card.innerHTML = `
        <span class="stamped-card-seal">SORÈVA</span>
        <img class="stamped-card-img" src="${currentSlide.image}" alt="${currentSlide.name}">
        <h4 class="stamped-card-title">${currentSlide.name}</h4>
        <div class="stamped-card-meta">
            <span>${formatPrice(currentSlide.priceINR)}</span>
            <span style="font-size: 0.65rem; color: var(--gold-hover);">Quick View <i class="fa-solid fa-arrow-right"></i></span>
        </div>
    `;

    // Clicking card opens quick view for this piece
    const prodId = currentSlide.productId;
    card.addEventListener('click', (ev) => {
        ev.stopPropagation();
        openQuickView(prodId);
    });

    container.appendChild(card);

    // Limit cards on screen to 5
    while (container.children.length > 5) {
        container.removeChild(container.firstChild);
    }

    // Auto-fade after 5.5 seconds
    setTimeout(() => {
        card.style.opacity = '0';
        setTimeout(() => card.remove(), 400);
    }, 5500);
}

// Spawn burst of golden shimmer sparkles
function spawnSparkles(x, y) {
    const canvas = document.getElementById('heroCanvas');
    if (!canvas) return;

    for (let i = 0; i < 8; i++) {
        const sparkle = document.createElement('span');
        sparkle.className = 'click-sparkle';
        const angle = Math.random() * Math.PI * 2;
        const dist = 35 + Math.random() * 55;
        sparkle.style.setProperty('--tx', `${Math.cos(angle) * dist}px`);
        sparkle.style.setProperty('--ty', `${Math.sin(angle) * dist}px`);
        sparkle.style.left = `${x}px`;
        sparkle.style.top = `${y}px`;
        sparkle.innerHTML = `<i class="fa-solid fa-sparkles"></i>`;
        canvas.appendChild(sparkle);

        setTimeout(() => sparkle.remove(), 750);
    }
}
