// ==========================================================================
// INNOVATIVE ATELIER ENTRY PAGE & WEIRD MOUSE ENGINE
// ==========================================================================

let entryActive = true;
let entryAnimId = null;

function initInnovativeAtelierEntry() {
    const entryEl = document.getElementById('entryExperience');
    const canvas = document.getElementById('entryCanvas');
    const droplet = document.getElementById('cursorDroplet');
    const loupe = document.getElementById('cursorLoupe');
    const letters = document.querySelectorAll('.entry-letter');

    if (!entryEl || !canvas || !droplet || !loupe) return;

    // --- State Variables ---
    const mouse = {
        x: window.innerWidth / 2,
        y: window.innerHeight / 2,
        prevX: window.innerWidth / 2,
        prevY: window.innerHeight / 2,
        vx: 0,
        vy: 0,
        speed: 0,
        isDown: false
    };

    const dropletPos = { x: mouse.x, y: mouse.y };
    const loupePos = { x: mouse.x, y: mouse.y };
    const ribbonHistory = [];
    const shockwaves = [];

    // --- Canvas Setup ---
    const ctx = canvas.getContext('2d');
    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    window.addEventListener('resize', () => {
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
    });

    // --- Particle Generation (Floating Gem Shards & Stardust) ---
    const NUM_PARTICLES = Math.min(130, Math.floor((width * height) / 12000));
    const particles = [];

    for (let i = 0; i < NUM_PARTICLES; i++) {
        particles.push({
            x: Math.random() * width,
            y: Math.random() * height,
            vx: (Math.random() - 0.5) * 0.8,
            vy: (Math.random() - 0.5) * 0.8,
            size: 2 + Math.random() * 5.5,
            sides: Math.random() > 0.4 ? 4 : (Math.random() > 0.5 ? 3 : 6), // diamonds, triangles, hexagons
            rotation: Math.random() * Math.PI * 2,
            vRot: (Math.random() - 0.5) * 0.03,
            baseAlpha: 0.25 + Math.random() * 0.55,
            alpha: 0.4,
            hue: Math.random() > 0.3 ? 42 : 38, // warm gold / champagne hues
            mass: 1 + Math.random() * 2
        });
    }

    // --- Mouse Listeners ---
    window.addEventListener('mousemove', (e) => {
        mouse.prevX = mouse.x;
        mouse.prevY = mouse.y;
        mouse.x = e.clientX;
        mouse.y = e.clientY;
        mouse.vx = mouse.x - mouse.prevX;
        mouse.vy = mouse.y - mouse.prevY;
        mouse.speed = Math.sqrt(mouse.vx * mouse.vx + mouse.vy * mouse.vy);

        // Record for ribbon trail
        ribbonHistory.push({ x: mouse.x, y: mouse.y, age: 0 });
        if (ribbonHistory.length > 24) ribbonHistory.shift();

        // Check hover over interactive items
        const target = e.target;
        const isInteractive = target && target.closest && target.closest('button, a, .entry-letter, .entry-scroll-cue, input, select');
        if (isInteractive) {
            droplet.classList.add('active-hover');
            loupe.classList.add('active-hover');
        } else {
            droplet.classList.remove('active-hover');
            loupe.classList.remove('active-hover');
        }
    });

    // Click / Shockwave Trigger
    window.addEventListener('mousedown', (e) => {
        mouse.isDown = true;
        // Spawn Shockwave
        shockwaves.push({
            x: e.clientX,
            y: e.clientY,
            radius: 5,
            maxRadius: Math.min(width, height) * 0.45,
            alpha: 1,
            speed: 14
        });

        // Letter elastic bounce on click
        letters.forEach((letter) => {
            letter.style.transition = 'transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
            letter.style.transform = `scale(0.88) translateZ(-35px)`;
            setTimeout(() => {
                letter.style.transform = '';
                setTimeout(() => { letter.style.transition = 'transform 0.12s ease-out'; }, 400);
            }, 100);
        });
    });

    window.addEventListener('mouseup', () => {
        mouse.isDown = false;
    });

    // Touch support
    window.addEventListener('touchmove', (e) => {
        if (e.touches.length > 0) {
            mouse.x = e.touches[0].clientX;
            mouse.y = e.touches[0].clientY;
        }
    }, { passive: true });

    // Wheel / Scroll to Unveil
    window.addEventListener('wheel', (e) => {
        if (entryActive && e.deltaY > 30) {
            closeEntryPrologue();
        }
    }, { passive: true });

    // Keyboard ESC to skip
    window.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && entryActive) {
            closeEntryPrologue();
        }
    });

    // --- Main Physics & Render Loop ---
    function render() {
        ctx.clearRect(0, 0, width, height);

        // 1. Update Custom Cursor Physics
        // Spring easing
        dropletPos.x += (mouse.x - dropletPos.x) * 0.4;
        dropletPos.y += (mouse.y - dropletPos.y) * 0.4;
        loupePos.x += (mouse.x - loupePos.x) * 0.14;
        loupePos.y += (mouse.y - loupePos.y) * 0.14;

        // Dynamic Velocity Squash & Stretch for Droplet
        const speed = Math.sqrt(mouse.vx * mouse.vx + mouse.vy * mouse.vy);
        const angle = Math.atan2(mouse.vy, mouse.vx);
        const stretch = Math.min(1.8, 1 + speed * 0.025);
        const squash = 1 / stretch;

        droplet.style.transform = `translate(${dropletPos.x}px, ${dropletPos.y}px) rotate(${angle}rad) scale(${stretch}, ${squash}) translate(-50%, -50%)`;
        loupe.style.transform = `translate(${loupePos.x}px, ${loupePos.y}px) translate(-50%, -50%)`;

        // Decay velocity
        mouse.vx *= 0.85;
        mouse.vy *= 0.85;

        // 2. Render Liquid Gold Ribbon Trail
        if (ribbonHistory.length > 2) {
            ctx.save();
            ctx.beginPath();
            ctx.moveTo(ribbonHistory[0].x, ribbonHistory[0].y);
            for (let i = 1; i < ribbonHistory.length - 1; i++) {
                const xc = (ribbonHistory[i].x + ribbonHistory[i + 1].x) / 2;
                const yc = (ribbonHistory[i].y + ribbonHistory[i + 1].y) / 2;
                ctx.quadraticCurveTo(ribbonHistory[i].x, ribbonHistory[i].y, xc, yc);
            }
            ctx.strokeStyle = 'rgba(223, 189, 124, 0.45)';
            ctx.lineWidth = Math.min(8, 2 + speed * 0.2);
            ctx.lineCap = 'round';
            ctx.shadowColor = '#c5a059';
            ctx.shadowBlur = 15;
            ctx.stroke();
            ctx.restore();
        }

        // Age ribbon
        for (let i = ribbonHistory.length - 1; i >= 0; i--) {
            ribbonHistory[i].age += 1;
            if (ribbonHistory[i].age > 18) ribbonHistory.splice(i, 1);
        }

        // 3. Render Shockwaves
        for (let s = shockwaves.length - 1; s >= 0; s--) {
            const sw = shockwaves[s];
            sw.radius += sw.speed;
            sw.alpha = Math.max(0, 1 - sw.radius / sw.maxRadius);

            if (sw.alpha <= 0) {
                shockwaves.splice(s, 1);
                continue;
            }

            ctx.save();
            ctx.beginPath();
            ctx.arc(sw.x, sw.y, sw.radius, 0, Math.PI * 2);
            ctx.strokeStyle = `rgba(223, 189, 124, ${sw.alpha * 0.75})`;
            ctx.lineWidth = 3;
            ctx.shadowColor = '#dfbd7c';
            ctx.shadowBlur = 20;
            ctx.stroke();

            // Prismatic Chromatic Outer Ring
            ctx.beginPath();
            ctx.arc(sw.x, sw.y, Math.max(1, sw.radius - 4), 0, Math.PI * 2);
            ctx.strokeStyle = `rgba(255, 100, 180, ${sw.alpha * 0.4})`;
            ctx.lineWidth = 1.5;
            ctx.stroke();

            ctx.beginPath();
            ctx.arc(sw.x, sw.y, sw.radius + 4, 0, Math.PI * 2);
            ctx.strokeStyle = `rgba(50, 220, 255, ${sw.alpha * 0.4})`;
            ctx.lineWidth = 1.5;
            ctx.stroke();
            ctx.restore();
        }

        // 4. Update & Draw Particles (Floating Crystals & Stardust)
        const vortexRadius = 260;

        for (let i = 0; i < particles.length; i++) {
            const p = particles[i];

            // Ambient float
            p.x += p.vx;
            p.y += p.vy;
            p.rotation += p.vRot;

            // Screen wrap
            if (p.x < -20) p.x = width + 20;
            if (p.x > width + 20) p.x = -20;
            if (p.y < -20) p.y = height + 20;
            if (p.y > height + 20) p.y = -20;

            // Magnetic Vortex Around Mouse
            const dx = mouse.x - p.x;
            const dy = mouse.y - p.y;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < vortexRadius && dist > 1) {
                const force = (1 - dist / vortexRadius) * 0.08;
                // Swirl tangential force
                const tx = -dy / dist;
                const ty = dx / dist;

                p.vx += tx * force * 1.5;
                p.vy += ty * force * 1.5;

                // Gentle radial suction/push
                const radialDir = dist < 70 ? -1 : 0.4;
                p.vx += (dx / dist) * force * radialDir;
                p.vy += (dy / dist) * force * radialDir;

                p.alpha = Math.min(1, p.baseAlpha + (1 - dist / vortexRadius) * 0.5);
            } else {
                // Return to gentle drift
                p.vx *= 0.96;
                p.vy *= 0.96;
                p.alpha += (p.baseAlpha - p.alpha) * 0.05;
            }

            // Repulsion from active shockwaves
            shockwaves.forEach(sw => {
                const sDist = Math.hypot(p.x - sw.x, p.y - sw.y);
                if (Math.abs(sDist - sw.radius) < 40) {
                    const angle = Math.atan2(p.y - sw.y, p.x - sw.x);
                    p.vx += Math.cos(angle) * 8 * sw.alpha;
                    p.vy += Math.sin(angle) * 8 * sw.alpha;
                }
            });

            // Render Crystal Polygon
            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.rotate(p.rotation);

            ctx.fillStyle = `hsla(${p.hue}, 65%, 68%, ${p.alpha})`;
            ctx.strokeStyle = `hsla(${p.hue}, 80%, 82%, ${p.alpha * 0.9})`;
            ctx.lineWidth = 1;
            ctx.shadowColor = '#c5a059';
            ctx.shadowBlur = 8;

            ctx.beginPath();
            if (p.sides === 4) {
                // Faceted Diamond shape
                ctx.moveTo(0, -p.size * 1.4);
                ctx.lineTo(p.size, 0);
                ctx.moveTo(0, -p.size * 1.4);
                ctx.lineTo(-p.size, 0);
                ctx.lineTo(0, p.size * 1.4);
                ctx.lineTo(p.size, 0);
                ctx.closePath();
                ctx.stroke();
                ctx.fill();
            } else if (p.sides === 3) {
                // Triangular facet
                ctx.moveTo(0, -p.size);
                ctx.lineTo(p.size * 0.86, p.size * 0.5);
                ctx.lineTo(-p.size * 0.86, p.size * 0.5);
                ctx.closePath();
                ctx.stroke();
                ctx.fill();
            } else {
                // Stardust point
                ctx.arc(0, 0, p.size * 0.6, 0, Math.PI * 2);
                ctx.fill();
            }
            ctx.restore();

            // Connect nearby facets with celestial filaments
            for (let j = i + 1; j < particles.length; j++) {
                const p2 = particles[j];
                const connDist = Math.hypot(p.x - p2.x, p.y - p2.y);
                if (connDist < 85) {
                    const connAlpha = (1 - connDist / 85) * 0.22 * p.alpha;
                    ctx.beginPath();
                    ctx.moveTo(p.x, p.y);
                    ctx.lineTo(p2.x, p2.y);
                    ctx.strokeStyle = `rgba(223, 189, 124, ${connAlpha})`;
                    ctx.lineWidth = 0.8;
                    ctx.stroke();
                }
            }
        }

        // 5. Interactive 3D Letter Physics (Sculpt the Light)
        if (entryActive) {
            letters.forEach(letter => {
                const rect = letter.getBoundingClientRect();
                const lx = rect.left + rect.width / 2;
                const ly = rect.top + rect.height / 2;
                const ldx = mouse.x - lx;
                const ldy = mouse.y - ly;
                const ldist = Math.hypot(ldx, ldy);

                if (ldist < 450) {
                    const factor = Math.pow(1 - ldist / 450, 1.8);
                    const rotY = (ldx / 450) * 32 * factor;
                    const rotX = -(ldy / 450) * 32 * factor;
                    const transZ = factor * 48;
                    const shadowX = -ldx * 0.15 * factor;
                    const shadowY = -ldy * 0.15 * factor;
                    const shadowBlur = 20 + factor * 35;

                    letter.style.transform = `perspective(1000px) rotateX(${rotX}deg) rotateY(${rotY}deg) translateZ(${transZ}px)`;
                    letter.style.filter = `drop-shadow(${shadowX}px ${shadowY}px ${shadowBlur}px rgba(223, 189, 124, ${0.4 + 0.5 * factor}))`;
                } else {
                    letter.style.transform = `perspective(1000px) rotateX(0deg) rotateY(0deg) translateZ(0px)`;
                    letter.style.filter = `drop-shadow(0 15px 35px rgba(0, 0, 0, 0.85))`;
                }
            });
        }

        entryAnimId = requestAnimationFrame(render);
    }

    // Start loop
    entryAnimId = requestAnimationFrame(render);
}

