// ==========================================================================
// MODERN MINIMALIST HAUTE JOAILLERIE ENTRY ENGINE
// ==========================================================================

let entryActive = true;
let entryAnimId = null;

function initInnovativeAtelierEntry() {
    const entryEl = document.getElementById('entryExperience');
    const canvas = document.getElementById('entryCanvas');
    const ambientLight = document.getElementById('entryAmbientLight');
    const brandWrap = document.getElementById('entryBrandWrap');

    if (!entryEl || !canvas) return;

    const ctx = canvas.getContext('2d');
    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    window.addEventListener('resize', () => {
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
    });

    // Subtle ambient mouse coordinates for soft parallax lighting
    const mouse = {
        x: width / 2,
        y: height / 2,
        targetX: width / 2,
        targetY: height / 2
    };

    window.addEventListener('mousemove', (e) => {
        mouse.targetX = e.clientX;
        mouse.targetY = e.clientY;
    });

    // Elegant, slow-drifting micro-stardust particles (subtle luxury gold embers)
    const NUM_STARDUST = Math.min(45, Math.floor((width * height) / 28000));
    const stardust = [];

    for (let i = 0; i < NUM_STARDUST; i++) {
        stardust.push({
            x: Math.random() * width,
            y: Math.random() * height,
            vx: (Math.random() - 0.5) * 0.25,
            vy: -0.15 - Math.random() * 0.35, // gentle upward ascent
            radius: 0.8 + Math.random() * 1.4,
            baseAlpha: 0.15 + Math.random() * 0.45,
            alpha: 0.2,
            pulseSpeed: 0.015 + Math.random() * 0.02,
            phase: Math.random() * Math.PI * 2
        });
    }

    // Scroll to unveil
    window.addEventListener('wheel', (e) => {
        if (entryActive && e.deltaY > 25) {
            closeEntryPrologue();
        }
    }, { passive: true });

    // Keyboard ESC to skip
    window.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && entryActive) {
            closeEntryPrologue();
        }
    });

    // Subtle render loop
    let tick = 0;

    function render() {
        if (!entryActive) return;

        ctx.clearRect(0, 0, width, height);
        tick += 0.02;

        // Smooth mouse interpolation for ambient lighting & subtle tilt
        mouse.x += (mouse.targetX - mouse.x) * 0.05;
        mouse.y += (mouse.targetY - mouse.y) * 0.05;

        // Dynamic ambient light position
        if (ambientLight) {
            const offsetX = (mouse.x - width / 2) * 0.08;
            const offsetY = (mouse.y - height / 2) * 0.08;
            ambientLight.style.transform = `translate(calc(-50% + ${offsetX.toFixed(1)}px), calc(-50% + ${offsetY.toFixed(1)}px))`;
        }

        // Whisper-soft 3D perspective tilt on the brand wrap
        if (brandWrap) {
            const tiltY = ((mouse.x / width) - 0.5) * 5;
            const tiltX = -((mouse.y / height) - 0.5) * 5;
            brandWrap.style.transform = `perspective(1200px) rotateX(${tiltX.toFixed(2)}deg) rotateY(${tiltY.toFixed(2)}deg)`;
        }

        // Render micro-stardust
        for (let i = 0; i < stardust.length; i++) {
            const p = stardust[i];

            p.x += p.vx;
            p.y += p.vy;

            // Gentle sinusoidal sway
            p.x += Math.sin(tick + p.phase) * 0.15;

            // Re-wrap when drifting off top or sides
            if (p.y < -10) {
                p.y = height + 10;
                p.x = Math.random() * width;
            }
            if (p.x < -10) p.x = width + 10;
            if (p.x > width + 10) p.x = -10;

            // Twinkle alpha
            p.alpha = p.baseAlpha + Math.sin(tick * 2 + p.phase) * 0.18;
            p.alpha = Math.max(0.08, Math.min(0.75, p.alpha));

            // Draw micro particle
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
            ctx.fillStyle = `rgba(223, 189, 124, ${p.alpha.toFixed(3)})`;
            ctx.shadowColor = '#dfbd7c';
            ctx.shadowBlur = 4;
            ctx.fill();
        }

        entryAnimId = requestAnimationFrame(render);
    }

    entryAnimId = requestAnimationFrame(render);
}

function closeEntryPrologue() {
    const entryEl = document.getElementById('entryExperience');
    if (!entryEl) return;

    entryActive = false;
    entryEl.classList.add('unveiled');
    document.body.classList.add('in-storefront');

    if (entryAnimId) {
        cancelAnimationFrame(entryAnimId);
        entryAnimId = null;
    }

