        barEl.style.transition = 'none';
        barEl.style.width = '0%';
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                barEl.style.transition = 'width 2.6s cubic-bezier(0.25, 1, 0.5, 1)';
                barEl.style.width = '100%';
            });
        });
    }

    // Automatically enter the website after 2.8 seconds
    entryAutoTimer = setTimeout(() => {
        if (entryActive) {
            closeEntryPrologue();
        }
    }, 2800);

    // Any keypress (ESC, Enter, Space) skips immediately
    const handleKey = (e) => {
        if (entryActive && (e.key === 'Escape' || e.key === ' ' || e.key === 'Enter')) {
            closeEntryPrologue();
            window.removeEventListener('keydown', handleKey);
        }
    };
    window.addEventListener('keydown', handleKey);

    // Any scroll or wheel skips immediately
    const handleWheel = (e) => {
        if (entryActive && Math.abs(e.deltaY) > 15) {
            closeEntryPrologue();
            window.removeEventListener('wheel', handleWheel);
        }
    };
    window.addEventListener('wheel', handleWheel, { passive: true });
}

function closeEntryPrologue() {
    const entryEl = document.getElementById('entryExperience');
    if (!entryEl) return;

    if (entryAutoTimer) {
        clearTimeout(entryAutoTimer);
        entryAutoTimer = null;
    }

    entryActive = false;
    entryEl.classList.add('unveiled');
    document.body.classList.add('in-storefront');

    // Smooth scroll down to main store if needed
    setTimeout(() => {
        const header = document.querySelector('.site-header');
        if (header) header.scrollIntoView({ behavior: 'smooth' });
    }, 150);

    showToast("Welcome to Sorèva");
}

function openEntryPrologue() {
    const entryEl = document.getElementById('entryExperience');
    if (!entryEl) return;

    entryActive = true;
    entryEl.classList.remove('unveiled');
    document.body.classList.remove('in-storefront');
    window.scrollTo({ top: 0, behavior: 'smooth' });

    // Restart the logo intro and auto-transition timer
    initInnovativeAtelierEntry();
}

