function initInnovativeAtelierEntry() {
    const entryEl = document.getElementById('entryExperience');
    const logoInner = document.getElementById('logoTypeInner');
    const subtitleLayer = document.getElementById('logoSubtitleLayer');
    const cursor = document.getElementById('logoTypeCursor');

    if (!entryEl) return;

    entryActive = true;
    entryEl.classList.remove('unveiled');
    document.body.classList.remove('in-storefront');

    // Clear previous timers
    if (entryAutoTimer) {
        clearTimeout(entryAutoTimer);
        entryAutoTimer = null;
    }
    logoTypingTimeouts.forEach(t => clearTimeout(t));
    logoTypingTimeouts = [];

    // Reset logo inner, subtitle layer and cursor state
    if (logoInner && cursor) {
        logoInner.style.clipPath = 'inset(0 100% 29% 0)';
        if (subtitleLayer) subtitleLayer.style.opacity = '0';
        cursor.style.left = '0%';
        cursor.style.opacity = '1';

        // 6 distinct typing steps matching the exact bounding boxes of "s o r è v a"
        const steps = [
            { pct: 13, delay: 180 },  // 's'
            { pct: 34, delay: 360 },  // 'o'
            { pct: 50, delay: 540 },  // 'r'
            { pct: 68, delay: 720 },  // 'è'
            { pct: 86, delay: 900 },  // 'v'
            { pct: 100, delay: 1080 } // 'a'
        ];

        steps.forEach(step => {
            const t = setTimeout(() => {
                if (!entryActive) return;
                logoInner.style.clipPath = `inset(0 ${100 - step.pct}% 29% 0)`;
                cursor.style.left = `${step.pct}%`;
            }, step.delay);
            logoTypingTimeouts.push(t);
        });

        // Gently reveal the subtitle ("exquisite jewellery") right after the wordmark finishes
        const subtitleTimer = setTimeout(() => {
            if (!entryActive || !subtitleLayer) return;
            subtitleLayer.style.opacity = '1';
        }, 1160);
        logoTypingTimeouts.push(subtitleTimer);

        // Fade out cursor gracefully after typing completes
        const cursorFadeTimer = setTimeout(() => {
            if (!entryActive) return;
            cursor.style.opacity = '0';
        }, 1550);
        logoTypingTimeouts.push(cursorFadeTimer);
    }

    // Automatically transition ahead into the website after typing presentation completes (~2.2s)
    entryAutoTimer = setTimeout(() => {
        if (entryActive) {
            closeEntryPrologue();
        }
    }, 2200);

